#!/bin/sh
# Map changed paths to the services that must be rebuilt.
base="${1:-origin/main}"
changed=$(git diff --name-only "$base"...HEAD)

[ -n "$changed" ] || { echo "nothing changed"; exit 0; }

services=""
for path in $changed; do
  case "$path" in
    services/*) svc=$(echo "$path" | cut -d/ -f2); services="$services $svc" ;;
    libs/*)     services="$services payments catalog search" ;;
    docs/*)     : ;;
    ci/*)       services="$services payments catalog search" ;;
  esac
done

for svc in $(echo $services | tr ' ' '\n' | sort -u); do
  [ -n "$svc" ] && echo "build: $svc"
done
